class Solution {
  private int[] digits;
  private int k;
  private long[][] memo;

  private long dfs(int pos, int last, boolean tight, boolean started) {
    if (pos == digits.length) return started ? 1 : 0;
    if (!tight && started && memo[pos][last] >= 0) return memo[pos][last];
    int limit = tight ? digits[pos] : 9;
    long res = 0;
    for (int d = 0; d <= limit; d++) {
      boolean nt = tight && d == limit;
      if (!started) {
        res += d == 0 ? dfs(pos + 1, 0, nt, false) : dfs(pos + 1, d, nt, true);
      } else if (Math.abs(d - last) <= k) {
        res += dfs(pos + 1, d, nt, true);
      }
    }
    if (!tight && started) memo[pos][last] = res;
    return res;
  }

  private long count(long n) {
    if (n <= 0) return 0;
    String s = Long.toString(n);
    digits = new int[s.length()];
    for (int i = 0; i < digits.length; i++) digits[i] = s.charAt(i) - '0';
    memo = new long[digits.length][10];
    for (long[] row : memo) java.util.Arrays.fill(row, -1);
    return dfs(0, 0, true, false);
  }

  public long goodIntegers(long l, long r, int k) {
    this.k = k;
    return count(r) - count(l - 1);
  }
}
